const body = $input.first().json.body;
let senderPhone = '';
let messageText = '';
let waId = '';

if (body?.entry) {
  const entry = body.entry[0];
  const change = entry?.changes[0];
  const msg = change?.value?.messages?.[0];
  if (!msg) return [];
  senderPhone = msg.from;
  messageText = msg.text?.body || '';
  waId = msg.id;
} else if (body?.From) {
  senderPhone = body.From.replace('whatsapp:', '').replace('+', '');
  messageText = body.Body || '';
  waId = body.MessageSid;
}

if (!senderPhone || !messageText) return [];

const text = messageText.toLowerCase();

const timePatterns = [
  { regex: /(\d{1,2})(?::(\d{2}))?\s*(?:am|a\.m\.)/i, isAM: true },
  { regex: /(\d{1,2})(?::(\d{2}))?\s*(?:pm|p\.m\.)/i, isPM: true },
  { regex: /(\d{1,2}):(\d{2})/, is24: true },
];

let detectedHour = -1;
for (const p of timePatterns) {
  const match = text.match(p.regex);
  if (match) {
    let h = parseInt(match[1]);
    if (p.isPM && h !== 12) h += 12;
    if (p.isAM && h === 12) h = 0;
    if (h >= 6 && h <= 23) { detectedHour = h; break; }
  }
}

const today = new Date();
let detectedDate = '';
if (text.includes('hoy') || text.includes('esta noche') || text.includes('esta tarde')) {
  detectedDate = today.toISOString().split('T')[0];
} else if (text.includes('ma') && (text.includes('ñana') || text.includes('nana'))) {
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);
  detectedDate = tomorrow.toISOString().split('T')[0];
} else {
  const days = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
  for (let i = 0; i < days.length; i++) {
    if (text.includes(days[i]) || text.includes(days[i].replace('e','é'))) {
      const diff = ((i - today.getDay()) + 7) % 7 || 7;
      const target = new Date(today);
      target.setDate(today.getDate() + diff);
      detectedDate = target.toISOString().split('T')[0];
      break;
    }
  }
}

const cleanPhone = senderPhone.replace(/^57/, '').slice(-10);

return [{ json: {
  senderPhone, cleanPhone, messageText, waId,
  detectedHour, detectedDate,
  canParseRequest: detectedHour >= 0
}}];

const data = $input.first().json;
const PITCH_ID = process.env.DEFAULT_PITCH_ID || 'REEMPLAZA_CON_TU_PITCH_ID';
const BASE_URL = process.env.APP_URL || 'https://tudominio.com';

const params = [];
if (data.detectedDate) params.push(`date=${data.detectedDate}`);
if (data.detectedHour >= 0) {
  const h = String(data.detectedHour).padStart(2, '0');
  params.push(`times=${h}:00`);
}
if (data.cleanPhone) params.push(`phone=${data.cleanPhone}`);

const bookingUrl = `${BASE_URL}/cancha/${PITCH_ID}?${params.join('&')}`;

const replyMessage = data.detectedDate
  ? `Hola! Aqui esta tu link para reservar:\n\n${bookingUrl}\n\nYa tiene la fecha y hora preseleccionadas. Solo confirma y sube tu comprobante de pago.`
  : `Hola! Aqui esta tu link para reservar la cancha:\n\n${bookingUrl}\n\nElige la fecha y hora que quieras. Es muy facil!`;

return [{ json: { ...data, bookingUrl, replyMessage } }];

